            tens = (q >> 4) & 0xF
            hundreds = (q >> 8) & 0xF
            thousands = (q >> 12) & 0xF
            if ones < 9:
                q += 1
            elif tens < 9:
                q = (q & 0xFFF0) + 0x10
            elif hundreds < 9:
                q = (q & 0xFF00) + 0x100
            elif thousands < 9:
                q = (q & 0xF000) + 0x1000
            else:
                q = 0
        # Rule ena_combinational
        ones = q & 0xF
        tens = (q >> 4) & 0xF
        hundreds = (q >> 8) & 0xF
        ena = 0
        if ones == 9:
            ena |= 1
        if tens == 9 and ones == 9:
